file.content:
  const raw = searchInput.value.trim();
  const tokens = [...raw.matchAll(/"([^"]+)"|(\S+)/g)].map(match => ({ value: (match[1] || match[2]).toLowerCase(), exact: Boolean(match[1]) }));
  showAdvancedMatches((item) => tokens.every((token) => {
    if (token.value.startsWith('label:')) return item.dataset.labels.split(' ').includes(token.value.slice(6));
    if (token.value.startsWith('-site:')) return !item.dataset.address.includes(token.value.slice(6));
    return item.dataset.search.includes(token.value);
  }));
}

function applyBuilderSearch() {
  const phrase = searchInput.value.trim().toLowerCase();
  const label = document.querySelector('#advanced-label').value;
  const excludedSite = document.querySelector('#advanced-exclude').value;
  showAdvancedMatches((item) => {
    const phraseMatches = !phrase || item.dataset.search.includes(phrase);
    const labelMatches = !label || item.dataset.labels.split(' ').includes(label);
    const siteAllowed = !excludedSite || !item.dataset.address.includes(excludedSite);
    return phraseMatches && labelMatches && siteAllowed;
  });
}

