document.querySelector('#settings-panel').addEventListener('submit', (event) => {
  event.preventDefault();
  const pageSize = document.querySelector('#page-size').value;
  const size = document.querySelector('#text-size').value;
  const order = document.querySelector('#default-order').value;
  document.querySelector('#settings-panel').classList.remove('show');
  document.querySelector('.save-panel').style.display = '';
  document.querySelector('.library-head').style.display = 'flex';
  libraryCards.forEach((item) => item.classList.add('show'));
  orderBookmarks(order);
  document.body.classList.toggle('text-large', size === 'large');
  document.querySelector('#page-status span').textContent = `Showing ${pageSize} per page · 247 bookmarks`;
  document.querySelector('#page-status').classList.add('show');
  document.querySelector('#result-count').textContent = '247 bookmarks';
  document.querySelector('h1').innerHTML = 'Your saved library.';
  document.querySelector('.lede').textContent = 'Your preferred view is ready whenever you return.';
  document.querySelectorAll('.nav-item').forEach((item) => item.classList.remove('active'));
  document.querySelector('#all-bookmarks-nav').classList.add('active');
  toast.textContent = 'Settings saved'; toast.classList.add('show');
  window.setTimeout(() => toast.classList.remove('show'), 1800);
});

